#include <iostream>
using namespace std;

double divide(int a, int b) {
    if (b == 0) {
        throw "Cannot divide by zero";
    }
    return (double)a / b;
}

int main() {
    try {
        cout << divide(10, 0);
    } catch (const char* msg) {
        cout << "Error: " << msg;
    }
    return 0;
}

